('ICS1113', 'Optimización', 'UC', 'Ingeniería', '2026-2', 'Programa del curso ICS1113 2026-2', '{"version":2,"eximicion":null,"dudas":[],"raiz":{"id":"raiz","nombre":"Nota final","tipo":"grupo","promedio":"ponderado","hijos":[{"id":"ne","nombre":"Nota de evaluaciones (NE)","peso":0.6,"tipo":"grupo","promedio":"sin_peor","minimo":3.95,"hijos":[{"id":"i1","nombre":"Interrogación 1","peso":0.25,"tipo":"nota","fecha":"2026-09-24","examen":false,"reemplazable":false,"minimo":null},{"id":"i2","nombre":"Interrogación 2","peso":0.25,"tipo":"nota","fecha":"2026-10-29","examen":false,"reemplazable":false,"minimo":null},{"id":"ex","nombre":"Examen","peso":0.5,"tipo":"nota","fecha":"2026-12-01","examen":true,"reemplazable":false,"minimo":null}]},{"id":"np","nombre":"Nota de proyecto (NP)","peso":0.25,"tipo":"nota","fecha":null,"examen":false,"reemplazable":false,"minimo":3.95},{"id":"nc","nombre":"Nota de controles (NC)","peso":0.15,"tipo":"nota","fecha":null,"examen":false,"reemplazable":false,"minimo":null}]},"reglas":["N = 0,6·NE + 0,25·NP + 0,15·NC.","NE = (I1 + I2 + 2·E − la peor de las tres) / 3: se borra la peor nota.","NE y NP deben ser ≥ 4,0 por separado; si no, la nota final es el mínimo entre N y 3,9.","NC = 1 + 6·mín(22, puntos)/22: 13 controles de 0 a 2 puntos, con 22 puntos ya tienes 7,0. Ingresa tu NC calculada.","Faltar a una interrogación es un 1,0 (se borra al ser la peor). No hay eximición del examen."]}'::jsonb, null)
